css:
.nm-chapter{--ink:#1a2b4a;--muted:#5b6b7f;--accent:#007acc;--warm:#b74b2b;--line:#d9dde3;--paper:#f7f8fa;color:var(--ink);font-family:Source Serif Pro,Georgia,serif;font-size:16px;line-height:1.6;}
.nm-header{margin-bottom:18px;}
.nm-title{font-size:28px;margin:0 0 6px 0;color:var(--ink);}
.nm-lead{font-size:16px;color:var(--muted);margin:0;}
.nm-layout{display:flex;gap:24px;align-items:flex-start;}
.nm-flow{flex:1 1 520px;}
.nm-stage{flex:0 0 520px;}
.nm-h2{font-size:20px;margin:18px 0 8px 0;}
.nm-p{margin:8px 0;}
.nm-formula{font-family:Source Serif Pro,Georgia,serif;font-size:18px;padding:10px 12px;border-left:3px solid var(--accent);background:rgba(0,122,204,0.06);margin:10px 0;}
.nm-controls{background:rgba(26,43,74,0.04);border:1px solid var(--line);border-radius:8px;padding:12px;margin:14px 0;}
.nm-label{display:block;font-size:14px;color:var(--muted);margin:8px 0 4px 0;}
.nm-readout{font-size:13px;color:var(--muted);margin-top:4px;}
.nm-buttons{display:flex;flex-wrap:wrap;gap:8px;margin-top:10px;}
.nm-btn,.nm-src-btn,.nm-con-btn,.nm-ask-btn{font-size:13px;padding:6px 10px;border:1px solid var(--line);background:#fff;color:var(--ink);border-radius:6px;cursor:pointer;}
.nm-btn:hover,.nm-src-btn:hover,.nm-con-btn:hover,.nm-ask-btn:hover{border-color:var(--accent);color:var(--accent);}
.nm-results{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-top:10px;}
.nm-kpi{border:1px solid var(--line);border-radius:8px;padding:10px;background:#fff;}
.nm-kpi-title{font-size:13px;color:var(--muted);}
.nm-kpi-value{font-size:18px;font-weight:600;margin-top:4px;}
.nm-unit{font-size:12px;color:var(--muted);font-weight:400;}
.nm-note{grid-column:1/-1;font-size:13px;color:var(--muted);margin-top:6px;}
.nm-stage canvas{width:100%;height:320px;display:block;border:1px solid var(--line);border-radius:8px;background:#fff;}
.nm-legend{display:flex;gap:12px;margin-top:8px;font-size:13px;color:var(--muted);}
.nm-dot{display:inline-block;width:10px;height:10px;border-radius:50%;margin-right:6px;}
.nm-dot-hy{background:#c62828;}
.nm-dot-r{background:#1565c0;}
.nm-dot-c{background:#2e7d32;}
.nm-critical{font-size:13px;color:var(--warm);margin-top:8px;}
.nm-footer{margin-top:18px;border-top:1px solid var(--line);padding-top:12px;}
.nm-h3{font-size:18px;margin:0 0 8px 0;}
.nm-list{margin:0 0 10px 18px;padding:0;}
.nm-list li{margin:4px 0;font-size:15px;}
.nm-sources{display:flex;flex-wrap:wrap;gap:8px;margin-top:8px;}
@media (max-width:900px){.nm-layout{flex-direction:column;}.nm-stage{flex:1 1 auto;}}
@media (prefers-reduced-motion: reduce){.nm-chapter *{transition:none !important;animation:none !important;}}
button[data-source]{background:#fff!important;color:#265976!important}

javascript:
(function(){
  'use strict';
  const canvas = document.getElementById('nm-canvas');
  const ctx = canvas ? canvas.getContext('2d') : null;
  const sliderP = document.getElementById('nm-err-slider');
  const sliderHx = document.getElementById('nm-hx-slider');
  const valP = document.getElementById('nm-p-val');
  const valHx = document.getElementById('nm-hx-val');
  const valHy = document.getElementById('nm-hy-val');
  const valR = document.getElementById('nm-r-val');
  const valC = document.getElementById('nm-c-val');
  const resetBtn = document.getElementById('nm-reset-btn');
  const acceptance = window.paperMindData && window.paperMindData.acceptance;

  function binaryEntropy(p){
    if (p <= 0 || p >= 1) return 0;
    return -(p * Math.log2(p) + (1 - p) * Math.log2(1 - p));
  }

  function compute(){
    const p = parseFloat(sliderP.value);
    const hx = parseFloat(sliderHx.value);
    const hy = binaryEntropy(p);
    const r = Math.max(0, hx - hy);
    const c = hx; // 教学示例：在二元对称信道且输入等概时，C = H(x) - H_y(x) 的最大值出现在该分布，此处用当前 H(x) 展示上限
    if (valP) valP.textContent = p.toFixed(3);
    if (valHx) valHx.textContent = hx.toFixed(2);
    if (valHy) valHy.textContent = hy.toFixed(3);
    if (valR) valR.textContent = r.toFixed(3);
    if (valC) valC.textContent = c.toFixed(3);
    return { p, hx, hy, r, c };
  }

  function draw(data){
    if (!ctx || !canvas) return;
    const W = canvas.width, H = canvas.height;
    ctx.clearRect(0,0,W,H);
    // 坐标：x=p[0..0.5], y=[0..1]
    const padL = 40, padR = 20, padT = 20, padB = 30;
    const plotW = W - padL - padR, plotH = H - padT - padB;
    function toX(p){ return padL + (p / 0.5) * plotW; }
    function toY(v){ return padT + (1 - v) * plotH; }

    // 网格与轴
    ctx.strokeStyle = '#d9dde3';
    ctx.lineWidth = 1;
    ctx.beginPath();
    for (let i=0;i<=5;i++){ const xv = i/10; const x = toX(xv*0.5); ctx.moveTo(x,padT); ctx.lineTo(x,H-padB); }
    for (let i=0;i<=4;i++){ const yv = i/4; const y = toY(yv); ctx.moveTo(padL,y); ctx.lineTo(W-padR,y); }
    ctx.stroke();

    // 轴标签
    ctx.fillStyle = '#5b6b7f';
    ctx.font = '12px Source Serif Pro, Georgia, serif';
    ctx.textAlign = 'center';
    ctx.fillText('误码率 p', W/2, H - 8);
    ctx.save();
    ctx.translate(12, H/2);
    ctx.rotate(-Math.PI/2);
    ctx.textAlign = 'center';
    ctx.fillText('bits/symbol', 0, 0);
    ctx.restore();

    // 曲线：H_y(x)
    ctx.strokeStyle = '#c62828';
    ctx.lineWidth = 2;
    ctx.beginPath();
    for (let i=0;i<=200;i++){
      const p = (i/200)*0.5;
      const hy = binaryEntropy(p);
      const x = toX(p), y = toY(Math.min(1, Math.max(0, hy)));
      if (i===0) ctx.moveTo(x,y); else ctx.lineTo(x,y);
    }
    ctx.stroke();

    // 曲线：R = H(x) - H_y(x)
    ctx.strokeStyle = '#1565c0';
    ctx.lineWidth = 2;
    ctx.beginPath();
    for (let i=0;i<=200;i++){
      const p = (i/200)*0.5;
      const hy = binaryEntropy(p);
      const r = Math.max(0, data.hx - hy);
      const x = toX(p), y = toY(Math.min(1, Math.max(0, r)));
      if (i===0) ctx.moveTo(x,y); else ctx.lineTo(x,y);
    }
    ctx.stroke();

    // 线：C（常数）
    ctx.strokeStyle = '#2e7d32';
    ctx.setLineDash([4,4]);
    ctx.lineWidth = 2;
    ctx.beginPath();
    const yC = toY(Math.min(1, Math.max(0, data.c)));
    ctx.moveTo(padL, yC);
    ctx.lineTo(W-padR, yC);
    ctx.stroke();
    ctx.setLineDash([]);

    // 当前点标记
    const xp = toX(data.p), yHy = toY(Math.min(1, Math.max(0, data.hy))), yR = toY(Math.min(1, Math.max(0, data.r)));
    ctx.fillStyle = '#c62828';
    ctx.beginPath(); ctx.arc(xp, yHy, 4, 0, Math.PI*2); ctx.fill();
    ctx.fillStyle = '#1565c0';
    ctx.beginPath(); ctx.arc(xp, yR, 4, 0, Math.PI*2); ctx.fill();
  }

  function update(){
    const data = compute();
    draw(data);
    if (acceptance && acceptance.update){
      try{ acceptance.update({ p: data.p, Hx: data.hx, Hy: data.hy, R: data.r, C: data.c }); }catch(e){}
    }
  }

  if (sliderP) sliderP.addEventListener('input', update);
  if (sliderHx) sliderHx.addEventListener('input', update);
  if (resetBtn) resetBtn.addEventListener('click', function(){
    if (sliderP) sliderP.value = 0.01;
    if (sliderHx) sliderHx.value = 1;
    update();
  });

  // 键盘可达性：左右箭头微调误码率
  if (sliderP){
    sliderP.addEventListener('keydown', function(e){
      const step = 0.001;
      if (e.key === 'ArrowLeft'){ sliderP.value = Math.max(0, parseFloat(sliderP.value) - step); update(); }
      if (e.key === 'ArrowRight'){ sliderP.value = Math.min(0.5, parseFloat(sliderP.value) + step); update(); }
    });
  }

  // 初始渲染
  update();
})();
